package com.personal.assistant.module.backup.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.backup.dto.BackupVerificationResponse;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.service.BackupService;import com.personal.assistant.module.security.service.SecurityAuditService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/operations/backups")public class BackupController{private final BackupService service;private final SecurityAuditService audit;public BackupController(BackupService service,SecurityAuditService audit){this.service=service;this.audit=audit;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping public ApiResponse<List<BackupRecord>>list(){return ApiResponse.success(service.list(uid()));}@PostMapping public ApiResponse<BackupRecord>run(HttpServletRequest request){BackupRecord r=service.runFullBackup(uid());audit.record(uid(),SecurityContextHelper.currentUser().username(),"BACKUP","BACKUP",String.valueOf(r.getId()),true,null,request);return ApiResponse.success(r);}@PostMapping("/{id}/verify")public ApiResponse<BackupVerificationResponse>verify(@PathVariable Long id,HttpServletRequest request){BackupVerificationResponse r=service.verify(uid(),id);audit.record(uid(),SecurityContextHelper.currentUser().username(),"VERIFY_BACKUP","BACKUP",String.valueOf(id),"VERIFIED".equals(r.status()),r.message(),request);return ApiResponse.success(r);}}
